// Counts how many values in the boolean condition are true.
fn count_true(condition: &[bool]) -> usize {
    condition.iter().filter(|&&b| b).count()
}

// Filters `arr` by the boolean mask `condition`. 
// Returns a new Vec<f32> containing elements of `arr` corresponding to true in `condition`.
// Assumes both inputs have the same length.
fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // It is assumed condition.len() == arr.len()

    // Pre-allocate space based on the count of true values to avoid multiple allocations
    let true_count = count_true(&condition);

    let mut result = Vec::with_capacity(true_count);

    for (cond, &val) in condition.iter().zip(&arr) {
        if *cond {
            result.push(val);
        }
    }

    // By construction, result.len() == number of true values in condition
    result
}